+    err?.retryAfterMs,
+    // Only a real 429/rate-limit error should trigger rate-limit escalation.
+    isRateLimitSignal(err)
+  );
+}
+
+export function checkLlmtrRateLimit(): void {
+  const now = Date.now();
+  const elapsed = now - lastLlmtrValidationTime;
+  if (elapsed < LLMTR_VALIDATION_MIN_INTERVAL_MS) {
+    lastLlmtrValidationTime = now + (LLMTR_VALIDATION_MIN_INTERVAL_MS - elapsed);
+    return;
+  }
+  lastLlmtrValidationTime = now;
 }
